            return FfiConverterString.lift(
    callWithPointer {
    uniffiRustCall() { _status ->
    UniffiLib.INSTANCE.uniffi_resonator_ffi_fn_method_entrainment_point(
        it, _status)
}
    }
    )
    }
    

    

    
    
    companion object
    
}

/**
 * @suppress
 */
public object FfiConverterTypeEntrainment: FfiConverter<Entrainment, Pointer> {

    override fun lower(value: Entrainment): Pointer {
        return value.uniffiClonePointer()
    }

    override fun lift(value: Pointer): Entrainment {
        return Entrainment(value)
    }

    override fun read(buf: ByteBuffer): Entrainment {
        // The Rust code always writes pointers as 8 bytes, and will
        // fail to compile if they don't fit.
        return lift(Pointer(buf.getLong()))
    }

    override fun allocationSize(value: Entrainment) = 8UL

    override fun write(value: Entrainment, buf: ByteBuffer) {
        // The Rust code always expects pointers written as 8 bytes,
        // and will fail to compile if they don't fit.
        buf.putLong(Pointer.nativeValue(lower(value)))
    }
}


