            FfiConverterString.write(value.`receivedAt`, buf)
            FfiConverterString.write(value.`body`, buf)
            FfiConverterOptionalString.write(value.`blobHash`, buf)
            FfiConverterOptionalString.write(value.`blobName`, buf)
            FfiConverterBoolean.write(value.`outgoing`, buf)
            FfiConverterOptionalString.write(value.`status`, buf)
    }
}



/**
