sealed class FfiException: kotlin.Exception() {
    
    /**
     * Connection, engine, protocol, or local failure.
     */
    class Failure(
        
        val `msg`: kotlin.String
        ) : FfiException() {
        override val message
            get() = "msg=${ `msg` }"
    }
    
    /**
     * The serving side's authenticator or policy said no.
     */
    class Denied(
        
        val `reason`: kotlin.String
        ) : FfiException() {
        override val message
            get() = "reason=${ `reason` }"
    }
    

    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<FfiException> {
        override fun lift(error_buf: RustBuffer.ByValue): FfiException = FfiConverterTypeFfiError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeFfiError : FfiConverterRustBuffer<FfiException> {
    override fun read(buf: ByteBuffer): FfiException {
        

        return when(buf.getInt()) {
            1 -> FfiException.Failure(
                FfiConverterString.read(buf),
                )
            2 -> FfiException.Denied(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: FfiException): ULong {
        return when(value) {
            is FfiException.Failure -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`msg`)
            )
            is FfiException.Denied -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`reason`)
            )
        }
    }

    override fun write(value: FfiException, buf: ByteBuffer) {
        when(value) {
            is FfiException.Failure -> {
                buf.putInt(1)
                FfiConverterString.write(value.`msg`, buf)
                Unit
            }
            is FfiException.Denied -> {
                buf.putInt(2)
                FfiConverterString.write(value.`reason`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}



/**
 * One envelope value crossing the FFI. `BlobRef` results (blobs beyond
 * the frame cap) arrive as `Text` carrying the `blake3:<hex>` hash.
 */
sealed class FfiValue {
    
    object Null : FfiValue()
    
    
    data class Integer(
        val `v`: kotlin.Long) : FfiValue() {
        companion object
    }
    
    data class Real(
        val `v`: kotlin.Double) : FfiValue() {
        companion object
    }
    
    data class Text(
        val `v`: kotlin.String) : FfiValue() {
        companion object
    }
    
    data class Blob(
        val `v`: kotlin.ByteArray) : FfiValue() {
        companion object
    }
    

    
    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeFfiValue : FfiConverterRustBuffer<FfiValue>{
    override fun read(buf: ByteBuffer): FfiValue {
        return when(buf.getInt()) {
            1 -> FfiValue.Null
            2 -> FfiValue.Integer(
                FfiConverterLong.read(buf),
                )
            3 -> FfiValue.Real(
                FfiConverterDouble.read(buf),
                )
            4 -> FfiValue.Text(
                FfiConverterString.read(buf),
                )
            5 -> FfiValue.Blob(
                FfiConverterByteArray.read(buf),
                )
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: FfiValue) = when(value) {
        is FfiValue.Null -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
        is FfiValue.Integer -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterLong.allocationSize(value.`v`)
            )
        }
        is FfiValue.Real -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterDouble.allocationSize(value.`v`)
            )
        }
        is FfiValue.Text -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`v`)
            )
        }
        is FfiValue.Blob -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterByteArray.allocationSize(value.`v`)
            )
        }
    }

    override fun write(value: FfiValue, buf: ByteBuffer) {
        when(value) {
            is FfiValue.Null -> {
                buf.putInt(1)
                Unit
            }
            is FfiValue.Integer -> {
                buf.putInt(2)
                FfiConverterLong.write(value.`v`, buf)
                Unit
            }
            is FfiValue.Real -> {
                buf.putInt(3)
                FfiConverterDouble.write(value.`v`, buf)
                Unit
            }
            is FfiValue.Text -> {
                buf.putInt(4)
                FfiConverterString.write(value.`v`, buf)
                Unit
            }
            is FfiValue.Blob -> {
                buf.putInt(5)
                FfiConverterByteArray.write(value.`v`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}






/**
 * @suppress
 */
public object FfiConverterOptionalLong: FfiConverterRustBuffer<kotlin.Long?> {
    override fun read(buf: ByteBuffer): kotlin.Long? {
        if (buf.get().toInt() == 0) {
            return null
        }
        return FfiConverterLong.read(buf)
    }

    override fun allocationSize(value: kotlin.Long?): ULong {
        if (value == null) {
            return 1UL
        } else {
            return 1UL + FfiConverterLong.allocationSize(value)
        }
    }

    override fun write(value: kotlin.Long?, buf: ByteBuffer) {
        if (value == null) {
            buf.put(0)
        } else {
            buf.put(1)
            FfiConverterLong.write(value, buf)
        }
    }
}




